            m_rresp_sync <= 2'b00;
        else
            m_rresp_sync <= m_rresp_reg;
    end

    // S-side R channel
    assign s_axil_rdata  = m_rdata_sync;
    assign s_axil_rresp  = m_rresp_sync;
    assign s_axil_rvalid = m_rvalid_sync;

    // M-side R ready
    assign m_axil_rready = s_rready_sync && !m_rvalid_reg;

